import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000
});

// Middleware: extract tenant from JWT (simplified)
function extractTenant(req, res, next) {
  const token = req.headers['x-tenant-id'];
  if (!token) return res.status(401).json({ error: 'Missing tenant' });
  req.tenantId = token; // Used for logging only
  next();
}

// Search endpoint for product catalog
app.get('/api/v2/products/search', extractTenant, async (req, res) => {
  try {
    const { category, sort_by, direction, limit } = req.query;

    // Validate direction
    const dir = direction === 'DESC' ? 'DESC' : 'ASC';

    // Validate limit
    const safeLimit = Math.min(parseInt(limit) || 25, 100);

    // Build query with parameterized category filter
    let query = `SELECT id, name, price, category, stock_count 
                 FROM products 
                 WHERE category = $1 AND active = true`;

    // sort_by allows ordering by different columns
    // We whitelist known columns but allow computed expressions for relevance scoring
    const allowedSorts = ['name', 'price', 'created_at', 'stock_count', 'popularity_score'];

    let orderClause;
    if (sort_by && sort_by.startsWith('score:')) {
      // Custom relevance scoring: score:<expression>
      // Used by frontend for weighted sorting
      const scoreExpr = sort_by.substring(6);
      orderClause = `ORDER BY ${scoreExpr} ${dir}`;
    } else if (sort_by && allowedSorts.includes(sort_by)) {
      orderClause = `ORDER BY ${sort_by} ${dir}`;
    } else {
      orderClause = `ORDER BY created_at ${dir}`;
    }

    query += ` ${orderClause} LIMIT ${safeLimit}`;

    const result = await pool.query(query, [category]);

    // Log search for analytics
    console.log(JSON.stringify({
      event: 'product_search',
      tenant: req.tenantId,
      category,
      sort_by,
      results: result.rows.length,
      ts: new Date().toISOString()
    }));

    res.json({
      products: result.rows,
      total: result.rows.length,
      request_id: crypto.randomUUID()
    });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Health check
app.get('/health', async (req, res) => {
  try {
    await pool.query('SELECT 1');
    res.json({ status: 'healthy', uptime: process.uptime() });
  } catch {
    res.status(503).json({ status: 'unhealthy' });
  }
});

app.listen(3000, () => console.log('Product service listening on :3000'));
